def svg(body,bg='#edece6'):
 return f'''<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 560 640" role="img"><defs><pattern id="grain" width="16" height="16" patternUnits="userSpaceOnUse"><circle cx="2" cy="3" r=".6" fill="#132b42" opacity=".08"/></pattern><filter id="shadow" x="-50%" y="-50%" width="200%" height="200%"><feGaussianBlur stdDeviation="15"/></filter></defs><rect width="560" height="640" fill="{bg}"/><path d="M0 530 L560 320" stroke="#1b3b53" opacity=".06" stroke-width="2"/><path d="M0 590 L560 380" stroke="#1b3b53" opacity=".06" stroke-width="2"/><ellipse cx="280" cy="548" rx="150" ry="24" fill="#152f48" opacity=".11" filter="url(#shadow)"/>{body}<rect width="560" height="640" fill="url(#grain)"/></svg>'''
